import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Button,
  FormActions,
  Input,
  Select,
  SearchInput,
  Card,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import type { ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { Title, Text, Tag, Space, Spin, Popconfirm } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import { createCompanySearchConfig } from '../../../components/search/companySearchConfig';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import type { PlanVoucherDraftDto } from '../../../services/fpc/types';
import styles from './PlanVoucherList.module.css';

const TEST_ID = 'plan-voucher-list';

const MONTH_LABELS: Record<number, string> = {
  1: 'Tháng 1', 2: 'Tháng 2', 3: 'Tháng 3', 4: 'Tháng 4',
  5: 'Tháng 5', 6: 'Tháng 6', 7: 'Tháng 7', 8: 'Tháng 8',
  9: 'Tháng 9', 10: 'Tháng 10', 11: 'Tháng 11', 12: 'Tháng 12',
};

const MONTH_OPTIONS = Array.from({ length: 12 }, (_, i) => ({
  value: i + 1,
  label: MONTH_LABELS[i + 1],
}));

const formatMoney = (v: number) =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

const PlanVoucherList: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const now = new Date();
  const { canManagePlanVoucher, canDeletePlanVoucher } = useFpcPermissions();

  const [items, setItems] = useState<PlanVoucherDraftDto[]>([]);
  const [loading, setLoading] = useState(false);
  const [planYear, setPlanYear] = useState(now.getFullYear());
  const [planMonth, setPlanMonth] = useState<number | ''>('');
  const [branchCode, setBranchCode] = useState('');
  const [selectedCompany, setSelectedCompany] = useState<ActiveCompanyItem | null>(null);
  const [searchText, setSearchText] = useState('');

  const companySearchConfig = useMemo(() => createCompanySearchConfig(), []);

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const list = await fpcService.getPlanVoucherList({
        planYear,
        planMonth: planMonth === '' ? undefined : planMonth,
        branchCode: branchCode || undefined,
        search: searchText.trim() || undefined,
      });
      setItems(list);
    } catch {
      dispatchAppToast(dispatch, { message: 'Không thể tải danh sách phiếu kế hoạch', type: 'error' });
    } finally {
      setLoading(false);
    }
  }, [dispatch, planYear, planMonth, branchCode, searchText]);

  useEffect(() => {
    fetchList();
  }, [fetchList]);

  const handleDelete = async (id: string) => {
    try {
      await fpcService.deletePlanVoucher(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa phiếu kế hoạch', type: 'success' });
      fetchList();
    } catch {
      dispatchAppToast(dispatch, { message: 'Lỗi khi xóa phiếu kế hoạch', type: 'error' });
    }
  };

  const handleBranchChange = (item: ActiveCompanyItem | null) => {
    setBranchCode(item?.code ?? item?.id ?? '');
    setSelectedCompany(item);
  };

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>Danh sách phiếu kế hoạch</Title>
            <Text type="secondary">Lập và theo dõi kế hoạch thu / chi theo kỳ</Text>
          </div>
          <FormActions align="end">
            <Button onClick={fetchList} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            {canManagePlanVoucher && (
              <Button variant="primary" onClick={() => navigate('/tc/ke-hoach/new')} data-testid={`${TEST_ID}-create-btn`}>
                <i className="fas fa-plus" /> Tạo mới
              </Button>
            )}
          </FormActions>
        </div>

        <div className={styles.filterRow}>
          <div className={styles.filterField}>
            <label className={styles.filterLabel}>Năm</label>
            <Input
              type="number"
              value={String(planYear)}
              onChange={e => setPlanYear(parseInt(e.target.value, 10) || now.getFullYear())}
              data-testid={`${TEST_ID}-filter-year`}
            />
          </div>
          <div className={styles.filterField}>
            <label className={styles.filterLabel}>Tháng</label>
            <Select
              value={planMonth === '' ? '' : planMonth}
              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                const v = e.target.value;
                setPlanMonth(v === '' ? '' : parseInt(v, 10));
              }}
              options={[{ value: '', label: 'Tất cả' }, ...MONTH_OPTIONS]}
              data-testid={`${TEST_ID}-filter-month`}
            />
          </div>
          <div className={styles.filterFieldWide}>
            <label className={styles.filterLabel}>Chi nhánh</label>
            <SearchInput
              config={companySearchConfig}
              value={branchCode}
              primaryDisplay={selectedCompany?.code}
              secondaryDisplay={selectedCompany?.name}
              onChange={item => handleBranchChange(item as ActiveCompanyItem)}
              onClear={() => handleBranchChange(null)}
              showLabel={false}
              placeholder="Tất cả chi nhánh..."
              data-testid={`${TEST_ID}-filter-branch`}
            />
          </div>
          <div className={styles.filterFieldWide}>
            <label className={styles.filterLabel}>Tìm kiếm</label>
            <Input
              value={searchText}
              onChange={e => setSearchText(e.target.value)}
              placeholder="Diễn giải..."
              data-testid={`${TEST_ID}-filter-search`}
            />
          </div>
        </div>
      </div>

      <Card>
        {loading ? (
          <div className={styles.loading}><Spin /> <Text>Đang tải...</Text></div>
        ) : items.length === 0 ? (
          <div className={styles.empty}>
            <Text type="secondary">Chưa có phiếu kế hoạch phù hợp bộ lọc</Text>
            {canManagePlanVoucher && (
              <Button variant="primary" onClick={() => navigate('/tc/ke-hoach/new')}>
                Tạo phiếu đầu tiên
              </Button>
            )}
          </div>
        ) : (
          <div className={styles.tableWrap}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Số phiếu</th>
                  <th>Ngày lập</th>
                  <th>Kỳ kế hoạch</th>
                  <th>Chi nhánh</th>
                  <th className={styles.colRight}>Tổng KH</th>
                  <th className={styles.colRight}>Thực tế</th>
                  <th className={styles.colRight}>Dòng</th>
                  <th>Trạng thái</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {items.map(item => (
                  <tr
                    key={item.id}
                    onClick={() => navigate(`/tc/ke-hoach/${item.id}`)}
                    className={styles.row}
                    data-testid={`${TEST_ID}-row-${item.id}`}
                  >
                    <td><strong>{item.code}</strong></td>
                    <td>{new Date(item.voucherDate).toLocaleDateString('vi-VN')}</td>
                    <td>
                      <Tag>{MONTH_LABELS[item.planMonth] ?? `T${item.planMonth}`}/{item.planYear}</Tag>
                    </td>
                    <td>{item.branchCode || '—'}</td>
                    <td className={styles.colRight}>{formatMoney(item.totalPlanned)}</td>
                    <td className={styles.colRight}>{formatMoney(item.totalActual)}</td>
                    <td className={styles.colRight}>{item.lineCount}</td>
                    <td>
                      <Tag color={item.status === 'Draft' ? 'blue' : 'green'}>
                        {item.status === 'Draft' ? 'Nháp' : 'Đã ghi'}
                      </Tag>
                    </td>
                    <td onClick={e => e.stopPropagation()}>
                      <Space>
                        <Button size="sm" onClick={() => navigate(`/tc/ke-hoach/${item.id}`)}>
                          {canManagePlanVoucher ? 'Sửa' : 'Mở'}
                        </Button>
                        {canDeletePlanVoucher && (
                          <Popconfirm title="Xóa phiếu kế hoạch này?" onConfirm={() => handleDelete(item.id)}>
                            <Button size="sm">Xóa</Button>
                          </Popconfirm>
                        )}
                      </Space>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
};

export default PlanVoucherList;
